// Legacy token alias ratchet: count `var(--neutral-*)`-style uses per CSS file and compare
// them with a committed cap. Pure functions only, so scripts/legacy-aliases.test.mjs covers
// them without a tree. The CLI is scripts/check-legacy-aliases.mjs.
//
// The legacy aliases are Bento's short names for Mux tokens, generated by
// scripts/sync-theme-presets.mjs. New CSS should use public Mux semantic tokens or
// --bento-* tokens, so the number of alias uses may only go down.

/** The legacy alias families the cap counts (the five named in docs/mux-ui-component-customisations.md). */
export const LEGACY_ALIAS_FAMILIES = ['neutral', 'color', 'space', 'radius', 'shadow'];

const ALIAS_USE = new RegExp(`var\\(\\s*--(?:${LEGACY_ALIAS_FAMILIES.join('|')})-`, 'g');

/** Number of `var(--<family>-...)` uses in a stylesheet, ignoring comments. */
export function countLegacyAliases(css) {
  return (css.replace(/\/\*[\s\S]*?\*\//g, '').match(ALIAS_USE) ?? []).length;
}

/** Validate cap JSON text and return `{ total, files }`. */
export function parseCap(text) {
  const parsed = JSON.parse(text);
  const { total, files } = parsed ?? {};
  if (!Number.isInteger(total) || total < 0) {
    throw new Error('Alias cap "total" must be a non-negative integer');
  }
  if (typeof files !== 'object' || files === null || Array.isArray(files)) {
    throw new Error('Alias cap must contain a "files" object');
  }
  for (const [file, count] of Object.entries(files)) {
    if (!Number.isInteger(count) || count <= 0) {
      throw new Error(`Alias cap entry ${file} must be a positive integer, got ${count}`);
    }
  }
  return { total, files };
}

/** Serialize a cap in the committed format (files sorted, zero counts omitted). */
export function formatCap(files) {
  const sorted = Object.fromEntries(
    Object.entries(files)
      .filter(([, count]) => count > 0)
      .sort(([left], [right]) => left.localeCompare(right)),
  );
  const total = Object.values(sorted).reduce((sum, count) => sum + count, 0);
  return `${JSON.stringify({ total, files: sorted }, null, 2)}\n`;
}

/**
 * Compare measured counts with the cap. A file fails when its count exceeds its cap (a file
 * absent from the cap has cap 0); the total fails when it exceeds `cap.total`. Counts below
 * the cap pass and are listed in `shrunk` so the cap can be lowered.
 *
 * @param {{ measured: Record<string, number>; cap: { total: number; files: Record<string, number> } }} input
 */
export function evaluateCounts({ measured, cap }) {
  const total = Object.values(measured).reduce((sum, count) => sum + count, 0);
  const grew = [];
  const shrunk = [];
  for (const [file, count] of Object.entries(measured)) {
    const allowed = cap.files[file] ?? 0;
    if (count > allowed) grew.push({ file, count, allowed });
    else if (count < allowed) shrunk.push({ file, count, allowed });
  }
  for (const [file, allowed] of Object.entries(cap.files)) {
    if (!(file in measured)) shrunk.push({ file, count: 0, allowed });
  }
  const totalGrew = total > cap.total;
  return { total, grew, shrunk, totalGrew, failed: totalGrew || grew.length > 0 };
}

/**
 * Compute a refreshed cap from fresh counts. A refresh only lowers: a file whose count rose
 * (or that has uses but no cap entry) keeps its previous cap unless named in `acceptGrowth`,
 * so a refresh cannot silently legalize new alias uses. Files with no uses drop out.
 *
 * @param {{ previous: Record<string, number>; measured: Record<string, number>; acceptGrowth?: string[] }} input
 */
export function refreshCap({ previous, measured, acceptGrowth = [] }) {
  const unknown = acceptGrowth.filter((file) => !(file in measured));
  if (unknown.length > 0) {
    throw new Error(`--accept-growth names files that were not scanned: ${unknown.join(', ')}`);
  }

  const accepted = new Set(acceptGrowth);
  const next = {};
  const lowered = [];
  const raised = [];
  const refused = [];
  for (const [file, count] of Object.entries(measured)) {
    const old = previous[file] ?? 0;
    if (count <= old || accepted.has(file)) {
      next[file] = count;
      if (count < old) lowered.push(file);
      else if (count > old) raised.push(file);
    } else {
      next[file] = old;
      refused.push(file);
    }
  }
  return { next, lowered, raised, refused };
}
